param([ValidateSet("anycpu","x86","x64")][string]$Platform="anycpu",[string]$OutputDirectory="bin")
$ErrorActionPreference = 'Stop'
$compiler = Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe'
New-Item -ItemType Directory -Force -Path (Join-Path $PSScriptRoot $OutputDirectory) | Out-Null
& $compiler /nologo /target:winexe /platform:$Platform /win32icon:"$PSScriptRoot\Assets\RianLogo.ico" /out:"$PSScriptRoot\$OutputDirectory\RianConverter.exe" "/resource:$PSScriptRoot\Dependencies\runtime.zip,RianConverter.Runtime.zip" /reference:"$PSScriptRoot\Dependencies\PdfSharp.dll" /reference:System.Web.Extensions.dll /reference:System.Windows.Forms.dll /reference:System.Drawing.dll /reference:System.Core.dll /reference:Microsoft.CSharp.dll /reference:System.Xml.Linq.dll /reference:System.IO.Compression.dll /reference:System.IO.Compression.FileSystem.dll /reference:"$env:WINDIR\Microsoft.NET\Framework64\v4.0.30319\WPF\UIAutomationClient.dll" /reference:"$env:WINDIR\Microsoft.NET\Framework64\v4.0.30319\WPF\UIAutomationTypes.dll" /reference:"$env:WINDIR\Microsoft.NET\Framework64\v4.0.30319\WPF\WindowsBase.dll" "$PSScriptRoot\Program.cs" "$PSScriptRoot\Converter.cs" "$PSScriptRoot\Formats.cs" "$PSScriptRoot\RuntimePack.cs" "$PSScriptRoot\PortablePdf.cs" "$PSScriptRoot\PortableDocuments.cs" "$PSScriptRoot\TableData.cs" "$PSScriptRoot\ExtraConversions.cs"
if ($LASTEXITCODE -ne 0) { throw 'Build failed.' }
